shellCommands.command:
node -e "
const r = require('react');
console.log('react version:', r.version);
console.log('has unstable_ViewTransition:', typeof r.unstable_ViewTransition);
console.log('has unstable_Activity:', typeof r.unstable_Activity);
console.log('has unstable_addTransitionType:', typeof r.unstable_addTransitionType);
const rd = require('react-dom');
console.log('react-dom version:', rd.version);
"

cd /workspace
node -e "console.log('bundled react:', require('./node_modules/next/dist/compiled/react/package.json').version)"
ls node_modules/next/dist/compiled/ | grep -i "^react" 
echo "=== experimental? ==="
node -e "
try {
  const r = require('./node_modules/next/dist/compiled/react-experimental/index.js');
  console.log('react-experimental ViewTransition:', typeof r.unstable_ViewTransition, 'addTransitionType:', typeof r.unstable_addTransitionType);
  console.log('ver', r.version);
} catch(e) { console.log('no react-experimental:', e.message) }
"

cd /workspace
node -e "
const r = require('./node_modules/next/dist/compiled/react-experimental/cjs/react.development.js');
console.log(Object.keys(r).sort().join('\n'));
" 2>&1 | head -50

cd /workspace
node -e "
const r = require('./node_modules/next/dist/compiled/react/cjs/react.development.js');
console.log('ver:', r.version);
console.log('ViewTransition:', typeof r.ViewTransition, '| unstable_ViewTransition:', typeof r.unstable_ViewTransition, '| addTransitionType:', typeof r.addTransitionType, '| unstable_addTransitionType:', typeof r.unstable_addTransitionType, '| Activity:', typeof r.Activity);
"
